import { useEffect, useRef } from "react";

const CursorFollower = () => {
  const dotRef = useRef(null);
  let x = 0,
    y = 0,
    targetX = 0,
    targetY = 0;

  useEffect(() => {
    const dot = dotRef.current;

    const updateTheme = () => {
      const isDark = document.documentElement.classList.contains("dark");
      dot.style.backgroundColor = isDark ? "#38bdf8" : "#1e40af"; // Tailwind: sky-400 / blue-900
      dot.style.boxShadow = isDark
        ? "0 0 12px #38bdf8"
        : "0 0 12px #1e3a8a";
    };

    // Initial theme and theme change observer
    updateTheme();
    const observer = new MutationObserver(updateTheme);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    // Track mouse
    const move = (e) => {
      targetX = e.clientX;
      targetY = e.clientY;
    };

    document.addEventListener("mousemove", move);

    // Animate smoothly
    const animate = () => {
      x += (targetX - x) * 0.15;
      y += (targetY - y) * 0.15;
      dot.style.transform = `translate(${x}px, ${y}px)`;
      requestAnimationFrame(animate);
    };
    animate();

    return () => {
      document.removeEventListener("mousemove", move);
      observer.disconnect();
    };
  }, []);

  return (
    <div
      ref={dotRef}
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        width: "18px",
        height: "18px",
        borderRadius: "50%",
        backgroundColor: "#1e40af", // default
        pointerEvents: "none",
        transform: "translate(-100px, -100px)",
        transition: "background-color 0.3s ease",
        zIndex: 9999,
        mixBlendMode: "difference", // cool visual blend
        boxShadow: "0 0 12px #1e3a8a", // default glow
      }}
    />
  );
};

export default CursorFollower;
