import { useState, useEffect } from "react";
import { motion } from "framer-motion";

const Hero = () => {
  const [theme, setTheme] = useState(localStorage.getItem("theme") || "light");

  useEffect(() => {
    const handleStorageChange = () => {
      setTheme(localStorage.getItem("theme") || "light");
    };

    window.addEventListener("storage", handleStorageChange);

    const observer = new MutationObserver(() => {
      setTheme(localStorage.getItem("theme") || "light");
    });

    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    return () => {
      window.removeEventListener("storage", handleStorageChange);
      observer.disconnect();
    };
  }, []);

  const logo = theme === "dark" ? "logo_w.png" : "logo_bb.png";

  return (
    <section
  className="relative flex flex-col items-center justify-center h-screen text-center px-6 
  bg-white dark:bg-gray-900 transition-all w-full overflow-hidden"
  id="Hero"
>

      {/* Logo */}
      <motion.div
        key={theme}
        initial={{ y: -10, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ duration: 1 }}
        className="mb-6"
      >
        <img src={logo} alt="Logo" className="w-32 h-32 rounded-full shadow-lg" />
      </motion.div>

      {/* Title */}
      <motion.h1
        initial={{ scale: 0.9, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        transition={{ duration: 1 }}
        className="text-5xl font-bold text-black dark:text-white"
      >
        Welcome to Digidit
      </motion.h1>

      {/* Subtitle */}
      <motion.p
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 1.2 }}
        className="text-lg text-black dark:text-gray-300 mt-3 max-w-2xl"
      >
        Video editing and post-production services for creators and brands, specializing in{" "}
        <span className="text-yellow-600 dark:text-yellow-400 font-semibold">Podcasts</span>,{" "}
        <span className="text-yellow-600 dark:text-yellow-400 font-semibold">Reels</span> and {" "}
        <span className="text-yellow-600 dark:text-yellow-400 font-semibold">YouTube Videos</span>. Whether
        We ensure high quality with a smooth process and complete projects without delays.
      </motion.p>
    </section>
  );
};

export default Hero;
